package com.contractguard.platform.organization;
import com.contractguard.platform.security.AuthPrincipal; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/organization") public class OrganizationController { private final OrganizationService service;public OrganizationController(OrganizationService service){this.service=service;} @GetMapping("/members")public List<OrganizationMemberResponse> members(@AuthenticationPrincipal AuthPrincipal p){return service.members(p);}@PostMapping("/members")public List<OrganizationMemberResponse> create(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody CreateMemberRequest r){return service.create(p,r);}@PutMapping("/members/{id}/roles")public List<OrganizationMemberResponse> roles(@AuthenticationPrincipal AuthPrincipal p,@PathVariable Long id,@Valid @RequestBody UpdateRolesRequest r){return service.roles(p,id,r);}@PostMapping("/members/{id}/status")public List<OrganizationMemberResponse> status(@AuthenticationPrincipal AuthPrincipal p,@PathVariable Long id,@RequestParam String value){return service.status(p,id,value);}@PostMapping("/contract-grants")public void grant(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody ContractGrantRequest r){service.grant(p,r);}@DeleteMapping("/contract-grants")public void revoke(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody ContractGrantRequest r){service.revoke(p,r);}}

